appearances.css:
.app{padding:6px;border-radius:4px;font-size:9px;display:grid;grid-template-columns:180px minmax(0,1fr);column-gap:6px;align-content:start}
.app>*{grid-column:1/-1}
.top{gap:4px 8px;margin:0 0 4px}
.sel{font-size:7.5px;gap:1px;letter-spacing:0}
select,button{font-size:9px;padding:3px 4px;border-radius:3px}
.app .vis{display:contents}
.vis canvas{grid-column:1;grid-row:2/span 2;width:180px!important;height:180px!important;object-fit:cover}
.pv{grid-column:2;grid-row:2;font-size:11px;line-height:14.5px;align-self:center}
.strip{grid-column:2;grid-row:3;height:62px!important;margin:0;width:100%}
.wrapx{overflow:visible}
.rows{grid-template-columns:minmax(0,1fr);gap:2px;margin:0}
.rh,.r{grid-template-columns:18px 22px repeat(3,minmax(0,1fr)) minmax(0,1.2fr) minmax(0,1.5fr) 26px minmax(0,1fr) 26px minmax(0,1.9fr) 26px;gap:3px}
.rh{font-size:6.5px;letter-spacing:0;text-align:center;white-space:nowrap}
.r select{padding:2px 0;font-size:8.5px;height:22px;text-align:center;text-align-last:center;appearance:none;-webkit-appearance:none;border-radius:3px}
.r .nr{padding:0;font-size:10px;line-height:22px;border-radius:3px}
.r .tog{padding:0;height:22px;font-size:10px;border-radius:3px}
.r>.kn{width:26px!important;height:26px!important;justify-self:center}
.r .kn svg,.c .kn svg{width:100%;height:100%}
h3{font-size:8px;margin:4px 0 3px;padding-top:3px}
.grid{grid-template-columns:repeat(8,minmax(0,1fr));gap:2px 3px}
.c{align-items:center;gap:0}
.c .lab{display:contents}
.c .lab span{order:3;text-transform:none;font-size:7.5px;text-align:center;white-space:normal;line-height:1.1;letter-spacing:-.02em;overflow:visible}
.c .lab output{order:2;font-size:8px;line-height:1.1}
.c>.kn{order:1;width:26px!important;height:26px!important;justify-self:center}
